# Builds the compiler of one commit like the Windows CI did at that commit and installs it to a folder: with tools/build.cmake
# (llvm-mingw) where the commit has it, before that with the Visual Studio generator (NASM, MSYS2 for FFmpeg). toolchain.txt in the
# folder names the bin folder of the clang that this blitzcc links programs with, to put first on PATH when it runs.
#   powershell -File benchmarks\build_windows.ps1 -Repo C:\claude-bench\repo -Commit <sha> -Out C:\claude-bench\scratch\x -Build C:\claude-bench\build
# The build folder is kept between commits, so the dependencies (ExternalContent) are only rebuilt when their sources change.
# Environment: BLITZLLVM_MSYS2 is the folder of MSYS2 (default C:\msys64), NASM must be on the PATH.
param([Parameter(Mandatory)] $Repo, [Parameter(Mandatory)] $Commit, [Parameter(Mandatory)] $Out, [Parameter(Mandatory)] $Build)
$ErrorActionPreference = "Stop"
$PSDefaultParameterValues["Out-File:Encoding"] = "utf8"  # Windows PowerShell writes the log as UTF-16 otherwise, which the Python side can not read.
# Compile the files of each project in parallel (MSVC compiles them one by one otherwise), also in the nested dependency builds.
$env:CL = "/MP"
$env:CMAKE_BUILD_PARALLEL_LEVEL = [string][Environment]::ProcessorCount
if (-not $env:BLITZLLVM_MSYS2) { $env:BLITZLLVM_MSYS2 = "C:\msys64" }
Set-Location $Repo
git checkout -q --detach $Commit
# Old commits do not have every submodule, so only the ones that exist at this commit are fetched.
$wanted = "cmake/version", "cmake/externalcontent", "third_party/Vulkan-Headers", "third_party/SDL", "third_party/SDL_image", "third_party/SDL_mixer", "third_party/stb", "third_party/VulkanMemoryAllocator", "third_party/FFmpeg", "third_party/JoltPhysics", "third_party/cgltf", "third_party/blitz3d", "third_party/blitzplus_msvc2017"
$present = @(git ls-files --stage | Where-Object { $_ -match '^160000' } | ForEach-Object { ($_ -split "\t")[1] })
$ErrorActionPreference = "Continue"
# The dav1d fix below is undone first, so that the submodule update can check out another dav1d.
if (Test-Path "third_party/SDL_image/external/dav1d/.git") { git -C third_party/SDL_image/external/dav1d checkout -- include/compat/msvc/stdatomic.h 2>&1 | Out-Null }
git submodule update --init --jobs 8 ($wanted | Where-Object { $present -contains $_ }) 2>&1 | Out-Null
# The codecs of SDL_image are fetched by the configure step (code_runtime/dependencies.cmake), after the fix below would run: dav1d is
# checked out here already, at the commit this SDL_image wants.
if (Test-Path "third_party/SDL_image/.gitmodules") {
    if (Select-String -Path "third_party/SDL_image/.gitmodules" -Pattern "external/dav1d" -SimpleMatch -Quiet) {
        git -C third_party/SDL_image submodule update --init --depth 1 external/dav1d 2>&1 | Out-Null
    }
}
# dav1d (in SDL_image) of the older commits has `#if defined(__clang__) && __has_include_next(<stdatomic.h>)` in its MSVC stdatomic.h, which
# MSVC 14.5x rejects (C7780, C1017: it parses the right side although __clang__ is not defined; older versions only warned). The same
# test, split so that MSVC only sees __has_include_next in a skipped group, is put into the checkout (a local change only, undone before the
# next commit).
$atomics = "third_party/SDL_image/external/dav1d/include/compat/msvc/stdatomic.h"
if (Test-Path $atomics) {
    $text = [IO.File]::ReadAllText((Resolve-Path $atomics))
    $old = "#if defined(__clang__) && __has_include_next(<stdatomic.h>)"
    if ($text.Contains($old)) {
        $new = "#if defined(__clang__)`n#  if __has_include_next(<stdatomic.h>)`n#    define DAV1D_MSVC_USE_CLANG_STDATOMIC`n#  endif`n#endif`n#if defined(DAV1D_MSVC_USE_CLANG_STDATOMIC)"
        [IO.File]::WriteAllText((Resolve-Path $atomics), $text.Replace($old, $new), (New-Object Text.UTF8Encoding $false))
    }
}
$ErrorActionPreference = "Continue"  # cmake and git write progress to stderr, which Windows PowerShell would turn into an error; the exit codes are checked.
New-Item -ItemType Directory -Force $Out | Out-Null
$log = Join-Path $Out "build.log"
if (Test-Path "tools/build.cmake") {
    # The commits since the one-stop build script (#696) build with it, with llvm-mingw's clang for the MinGW target, as CI does: their
    # code no longer builds with MSVC. Its own build folder, so the Visual Studio one of the older commits is kept.
    cmake -P tools/build.cmake -- --build-dir "$Build-mingw" --install $Out --msys2 $env:BLITZLLVM_MSYS2 *> $log
    if ($LASTEXITCODE -ne 0) { exit 2 }
    # The programs that this blitzcc builds are linked by the same clang.
    $clang = Get-ChildItem (Join-Path $Repo ".tools") -Recurse -Filter clang.exe -ErrorAction SilentlyContinue | Where-Object { $_.FullName -match "llvm-mingw" } | Select-Object -First 1
    if ($clang) { Set-Content -Path (Join-Path $Out "toolchain.txt") -Value $clang.DirectoryName }
    exit 0
}
cmake -S . -B $Build -G "Visual Studio 18 2026" -A x64 -DBLITZLLVM_REQUIRE_NASM=ON *> $log
if ($LASTEXITCODE -ne 0 -and (Select-String -Path $log -Pattern "did not install the licenses" -Quiet)) {
    # The dependencies of the kept build folder were made without something that this commit adds (Opus, for example): build them again, once.
    Remove-Item -Recurse -Force (Join-Path $Build "ExternalContentFiles") -ErrorAction SilentlyContinue
    cmake -S . -B $Build -G "Visual Studio 18 2026" -A x64 -DBLITZLLVM_REQUIRE_NASM=ON *>> $log
}
if ($LASTEXITCODE -ne 0) { exit 2 }
cmake --build $Build --config Release --parallel *>> $log
if ($LASTEXITCODE -ne 0) { exit 2 }
cmake --install $Build --config Release --prefix $Out *>> $log
if ($LASTEXITCODE -ne 0) { exit 2 }
# The first commits only have the compiler and no install rule: its compiler.exe is what the later commits call blitzcc.exe.
if (-not (Get-ChildItem $Out -Recurse -Filter blitzcc.exe)) {
    $compiler = Get-ChildItem $Build -Recurse -Filter compiler.exe | Where-Object { $_.FullName -match "Release" } | Select-Object -First 1
    if ($compiler) { Copy-Item $compiler.FullName (Join-Path $Out "blitzcc.exe") }
}
# A blitzcc built with MSVC links the programs with a clang for the MSVC target (LLVM's own; BLITZLLVM_LLVM is its bin folder).
$llvm = if ($env:BLITZLLVM_LLVM) { $env:BLITZLLVM_LLVM } else { "C:\Program Files\LLVM\bin" }
Set-Content -Path (Join-Path $Out "toolchain.txt") -Value $llvm
